namespace RaceDay.API.Models;
public class Event { public int EventId { get; set; } public int OrganiserId { get; set; } public User? Organiser { get; set; } public string Title { get; set; } = string.Empty; public string? Description { get; set; } public string? BannerImageUrl { get; set; } public string Location { get; set; } = string.Empty; public DateTime EventDate { get; set; } public string EventType { get; set; } = "Run"; public string Status { get; set; } = "Draft"; public DateTime CreatedAt { get; set; } = DateTime.UtcNow; public ICollection<Category> Categories { get; set; } = new List<Category>(); public ICollection<Enrolment> Enrolments { get; set; } = new List<Enrolment>(); }